    {
      "id": "q-1:1-arabicPublishedParent",
      "text": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ"
    },
    {
      "id": "q-1:1-publishedUzbekFullParent",
      "text": "Меҳрибон ва Раҳмли Аллоҳ номи билан (бошлайман)."
    },
    {
      "id": "q-1:1-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-1:2",
      "text": "1:2"
    },
    {
      "id": "q-1:2-arabicPublishedParent",
      "text": "ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ"
    },
    {
      "id": "q-1:2-publishedUzbekFullParent",
      "text": "Ҳамд оламлар Парвардигори Аллоҳникидир."
    },
    {
      "id": "q-1:2-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-1:3",
      "text": "1:3"
    },
    {
      "id": "q-1:3-arabicPublishedParent",
      "text": "ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ"
    },
    {
      "id": "q-1:3-publishedUzbekFullParent",
      "text": "Меҳрибон ва Раҳмли."
    },
    {
      "id": "q-1:3-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-1:4",
      "text": "1:4"
    },
    {
      "id": "q-1:4-arabicPublishedParent",
      "text": "مَٰلِكِ يَوۡمِ ٱلدِّينِ"
    },
    {
      "id": "q-1:4-publishedUzbekFullParent",
      "text": "Қиёмат кунининг Эгаси."
    },
    {
      "id": "q-1:4-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-1:5",
      "text": "1:5"
    },
    {
      "id": "q-1:5-arabicPublishedParent",
      "text": "إِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَعِينُ"
    },
    {
      "id": "q-1:5-publishedUzbekFullParent",
      "text": "Сенгагина ибодат қиламиз ва Сендангина ёрдам сўраймиз."
    },
    {
      "id": "q-1:5-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-1:6",
      "text": "1:6"
    },
    {
      "id": "q-1:6-arabicPublishedParent",
      "text": "ٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ"
    },
    {
      "id": "q-1:6-publishedUzbekFullParent",
      "text": "Бизни тўғри йўлга йўллагин."
    },
    {
      "id": "q-1:6-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-1:7",
      "text": "1:7"
    },
    {
      "id": "q-1:7-arabicPublishedParent",
      "text": "صِرَٰطَ ٱلَّذِينَ أَنۡعَمۡتَ عَلَيۡهِمۡ غَيۡرِ ٱلۡمَغۡضُوبِ عَلَيۡهِمۡ وَلَا ٱلضَّآلِّينَ"
    },
    {
      "id": "q-1:7-publishedUzbekFullParent",
      "text": "Ўзинг неъмат берганларинг йўлига. Ғазабга учраганлар ва адашганларнинг (йўлига) эмас."
    },
    {
      "id": "q-1:7-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-2:4",
      "text": "2:4"
    },
    {
      "id": "q-2:4-arabicPublishedParent",
      "text": "وَٱلَّذِينَ يُؤۡمِنُونَ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَ وَبِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ"
    },
    {
      "id": "q-2:4-publishedUzbekFullParent",
      "text": "(Тақводорларки,) сизга нозил қилинган (ваҳий)га ҳам, сиздан олдинги (пайғамбар)ларга нозил қилинган (ваҳий)га ҳам иймон келтирурлар ва охиратга аниқ ишонурлар."
    },
    {
      "id": "q-2:4-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-2:255",
      "text": "2:255"
    },
    {
      "id": "q-2:255-arabicPublishedParent",
      "text": "ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا يَـُٔودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ"
    },
    {
      "id": "q-2:255-publishedUzbekFullParent",
      "text": "Аллоҳ. Ундан ўзга илоҳ йўқ. У Тирикдир ва Қайюмдир. Уни мудроқ ҳам, уйқу ҳам олмас. Осмонлару ердаги нарсалар Уникидир. Унинг ҳузурида Ўзининг изнисиз ҳеч ким шафоат қила олмас. У уларнинг олдиларидаги нарсани ҳам, ортларидаги нарсани ҳам билур. Унинг илмидан ҳеч нарсани иҳота қила олмаслар. Ўзи истагани бундан мустасно. Унинг курсиси осмонлару ерни қамраган. У уларни муҳофаза қилишдан чарчамас. У энг Юксак ва Буюкдир."
    },
    {
      "id": "q-2:255-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-6:137",
      "text": "6:137"
    },
    {
      "id": "q-6:137-arabicPublishedParent",
      "text": "وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٖ مِّنَ ٱلۡمُشۡرِكِينَ قَتۡلَ أَوۡلَٰدِهِمۡ شُرَكَآؤُهُمۡ لِيُرۡدُوهُمۡ وَلِيَلۡبِسُواْ عَلَيۡهِمۡ دِينَهُمۡۖ وَلَوۡ شَآءَ ٱللَّهُ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ"
    },
    {
      "id": "q-6:137-publishedUzbekFullParent",
      "text": "Шунингдек, мушриклардан кўпларига шериклари уларни ҳалок этиш ва динларини чалкаштириб юбориш учун болаларини ўлдиришни чиройли қилиб кўрсатди. Аллоҳ хоҳлаганида бундай қилмаган бўлардилар. Бас, уларни туҳмат-бўҳтонлари билан тарк қилинг!"
    },
    {
      "id": "q-6:137-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-7:175",
      "text": "7:175"
    },
    {
      "id": "q-7:175-arabicPublishedParent",
      "text": "وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱلَّذِيٓ ءَاتَيۡنَٰهُ ءَايَٰتِنَا فَٱنسَلَخَ مِنۡهَا فَأَتۡبَعَهُ ٱلشَّيۡطَٰنُ فَكَانَ مِنَ ٱلۡغَاوِينَ"
    },
    {
      "id": "q-7:175-publishedUzbekFullParent",
      "text": "Уларга бир кимсанинг хабарини тиловат қилингки, унга оятларимизни билдирган эдик. У эса оятларимиздан четлади. (Натижада) уни шайтон эргаштириб кетиб, йўлдан озгувчилардан бўлиб қолди."
    },
    {
      "id": "q-7:175-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-10:11",
      "text": "10:11"
    },
    {
      "id": "q-10:11-arabicPublishedParent",
      "text": "۞ وَلَوۡ يُعَجِّلُ ٱللَّهُ لِلنَّاسِ ٱلشَّرَّ ٱسۡتِعۡجَالَهُم بِٱلۡخَيۡرِ لَقُضِيَ إِلَيۡهِمۡ أَجَلُهُمۡۖ فَنَذَرُ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ"
    },
    {
      "id": "q-10:11-publishedUzbekFullParent",
      "text": "Агар Аллоҳ одамларга яхшиликни тез келтиргани каби ёмонликни ҳам нақд қилса эди, албатта, уларнинг ажаллари етган бўлур эди. Бас, Бизга рўбарў бўлишни умид қилмайдиган кимсаларни ўз туғёнларида адашиб юришларига қўйиб берамиз."
    },
    {
      "id": "q-10:11-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-14:34",
      "text": "14:34"
    },
    {
      "id": "q-14:34-arabicPublishedParent",
      "text": "وَءَاتَىٰكُم مِّن كُلِّ مَا سَأَلۡتُمُوهُۚ وَإِن تَعُدُّواْ نِعۡمَتَ ٱللَّهِ لَا تُحۡصُوهَآۗ إِنَّ ٱلۡإِنسَٰنَ لَظَلُومٞ كَفَّارٞ"
    },
    {
      "id": "q-14:34-publishedUzbekFullParent",
      "text": "Сизларга сўраган нарсаларингизнинг ҳаммасидан берди. Аллоҳнинг неъматларини санаб, саноғига ета олмайсизлар. Албатта, инсон зоти ўта золим ва нонкўрдир."
    },
    {
      "id": "q-14:34-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-14:35",
      "text": "14:35"
    },
    {
      "id": "q-14:35-arabicPublishedParent",
      "text": "وَإِذۡ قَالَ إِبۡرَٰهِيمُ رَبِّ ٱجۡعَلۡ هَٰذَا ٱلۡبَلَدَ ءَامِنٗا وَٱجۡنُبۡنِي وَبَنِيَّ أَن نَّعۡبُدَ ٱلۡأَصۡنَامَ"
    },
    {
      "id": "q-14:35-publishedUzbekFullParent",
      "text": "Эсланг! Иброҳим деди: «Парвардигоро, бу шаҳарни тинч қилгин, мени ва болаларимни бутларга ибодат қилишдан йироқ айлагин."
    },
    {
      "id": "q-14:35-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-14:42",
      "text": "14:42"
    },
    {
      "id": "q-14:42-arabicPublishedParent",
      "text": "وَلَا تَحۡسَبَنَّ ٱللَّهَ غَٰفِلًا عَمَّا يَعۡمَلُ ٱلظَّٰلِمُونَۚ إِنَّمَا يُؤَخِّرُهُمۡ لِيَوۡمٖ تَشۡخَصُ فِيهِ ٱلۡأَبۡصَٰرُ"
    },
    {
      "id": "q-14:42-publishedUzbekFullParent",
      "text": "Сиз Аллоҳ золимлар қилаётган ишлардан бехабар, деб ўйламанг. Фақат уларни кўзлар қотиб қоладиган кун учун кечиктириб турибди, холос."
    },
    {
      "id": "q-14:42-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-15:87",
      "text": "15:87"
    },
    {
      "id": "q-15:87-arabicPublishedParent",
      "text": "وَلَقَدۡ ءَاتَيۡنَٰكَ سَبۡعٗا مِّنَ ٱلۡمَثَانِي وَٱلۡقُرۡءَانَ ٱلۡعَظِيمَ"
    },
    {
      "id": "q-15:87-publishedUzbekFullParent",
      "text": "Дарҳақиқат, сизга етти такрорланувчини ва улуғ Қуръонни бердик."
    },
    {
      "id": "q-15:87-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-15:88",
      "text": "15:88"
    },
    {
      "id": "q-15:88-arabicPublishedParent",
      "text": "لَا تَمُدَّنَّ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّنۡهُمۡ وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَٱخۡفِضۡ جَنَاحَكَ لِلۡمُؤۡمِنِينَ"
    },
    {
      "id": "q-15:88-publishedUzbekFullParent",
      "text": "Улардан айримларига Биз ато этган нарсаларга кўзингизни тикманг. Улар учун хафа ҳам бўлманг. Мўминлар учун қанотингизни паст тутинг."
    },
    {
      "id": "q-15:88-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-18:1",
      "text": "18:1"
    },
    {
      "id": "q-18:1-arabicPublishedParent",
      "text": "ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِيٓ أَنزَلَ عَلَىٰ عَبۡدِهِ ٱلۡكِتَٰبَ وَلَمۡ يَجۡعَل لَّهُۥ عِوَجَاۜ"
    },
    {
      "id": "q-18:1-publishedUzbekFullParent",
      "text": "Бандасига китоб тушириб, унда биронта эгрилик қўймаган Аллоҳга ҳамд бўлсин!"
    },
    {
      "id": "q-18:1-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-19:98",
      "text": "19:98"
    },
    {
      "id": "q-19:98-arabicPublishedParent",
      "text": "وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هَلۡ تُحِسُّ مِنۡهُم مِّنۡ أَحَدٍ أَوۡ تَسۡمَعُ لَهُمۡ رِكۡزَۢا"
    },
    {
      "id": "q-19:98-publishedUzbekFullParent",
      "text": "Улардан олдин қанча асрни ҳалок қилдик. Улардан бирортасини кўрасизми ёки шарпасини эшитасизми?!"
    },
    {
      "id": "q-19:98-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-20:111",
      "text": "20:111"
    },
    {
      "id": "q-20:111-arabicPublishedParent",
      "text": "۞ وَعَنَتِ ٱلۡوُجُوهُ لِلۡحَيِّ ٱلۡقَيُّومِۖ وَقَدۡ خَابَ مَنۡ حَمَلَ ظُلۡمٗا"
    },
    {
      "id": "q-20:111-publishedUzbekFullParent",
      "text": "Юзлар тирик ва абадий Зотга бош эгди. Зулмни кўтариб келган кимса аниқ ноумид бўлди."
    },
    {
      "id": "q-20:111-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-20:115",
      "text": "20:115"
    },
    {
      "id": "q-20:115-arabicPublishedParent",
      "text": "وَلَقَدۡ عَهِدۡنَآ إِلَىٰٓ ءَادَمَ مِن قَبۡلُ فَنَسِيَ وَلَمۡ نَجِدۡ لَهُۥ عَزۡمٗا"
    },
    {
      "id": "q-20:115-publishedUzbekFullParent",
      "text": "Дарҳақиқат, Биз илгари Одам билан ҳам аҳдлашган эдик. У эса унутди ва Биз унда собитқадамликни кўрмадик."
    },
    {
      "id": "q-20:115-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-21:30",
      "text": "21:30"
    },
    {
      "id": "q-21:30-arabicPublishedParent",
      "text": "أَوَلَمۡ يَرَ ٱلَّذِينَ كَفَرُوٓاْ أَنَّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ كَانَتَا رَتۡقٗا فَفَتَقۡنَٰهُمَاۖ وَجَعَلۡنَا مِنَ ٱلۡمَآءِ كُلَّ شَيۡءٍ حَيٍّۚ أَفَلَا يُؤۡمِنُونَ"
    },
    {
      "id": "q-21:30-publishedUzbekFullParent",
      "text": "Куфр келтирган кимсалар осмонлару ер қапишган бўлиб, кейин уларни ажратганимизни ва ҳамма жонли нарсани сувдан (ҳосил) қилганимизни билмасларми? Иймон келтирмайдиларми?"
    },
    {
      "id": "q-21:30-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-21:47",
      "text": "21:47"
    },
    {
      "id": "q-21:47-arabicPublishedParent",
      "text": "وَنَضَعُ ٱلۡمَوَٰزِينَ ٱلۡقِسۡطَ لِيَوۡمِ ٱلۡقِيَٰمَةِ فَلَا تُظۡلَمُ نَفۡسٞ شَيۡـٔٗاۖ وَإِن كَانَ مِثۡقَالَ حَبَّةٖ مِّنۡ خَرۡدَلٍ أَتَيۡنَا بِهَاۗ وَكَفَىٰ بِنَا حَٰسِبِينَ"
    },
    {
      "id": "q-21:47-publishedUzbekFullParent",
      "text": "Биз Қиёмат куни учун адолатли тарозилар қўюрмиз, бас, биронта жон заррача зулм қилинмас. Бир хардал уруғидек бўлса ҳам, ўшани-да келтирурмиз! Ҳисоб-китоб қилувчиликда Ўзимиз етарлимиз."
    },
    {
      "id": "q-21:47-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-39:6",
      "text": "39:6"
    },
    {
      "id": "q-39:6-arabicPublishedParent",
      "text": "خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ ثُمَّ جَعَلَ مِنۡهَا زَوۡجَهَا وَأَنزَلَ لَكُم مِّنَ ٱلۡأَنۡعَٰمِ ثَمَٰنِيَةَ أَزۡوَٰجٖۚ يَخۡلُقُكُمۡ فِي بُطُونِ أُمَّهَٰتِكُمۡ خَلۡقٗا مِّنۢ بَعۡدِ خَلۡقٖ فِي ظُلُمَٰتٖ ثَلَٰثٖۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۖ لَآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُصۡرَفُونَ"
    },
    {
      "id": "q-39:6-publishedUzbekFullParent",
      "text": "У сизларни бир жондан яратди, кейин ундан жуфтини яратди ва сизларга чорва ҳайвонларидан саккиз жуфтни туширди. У сизларни оналарингиз қорнида уч зулмат ичида бир яратишдан кейин яна бошқа яратишга ўтказиб, аста-секин яратур. Ана ўша Аллоҳ Парвардигорингиздир. Барча мулк Уникидир. Ундан ўзга илоҳ йўқ. Бас, қаён бурилиб кетмоқдасизлар?!"
    },
    {
      "id": "q-39:6-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-40:16",
      "text": "40:16"
    },
    {
      "id": "q-40:16-arabicPublishedParent",
      "text": "يَوۡمَ هُم بَٰرِزُونَۖ لَا يَخۡفَىٰ عَلَى ٱللَّهِ مِنۡهُمۡ شَيۡءٞۚ لِّمَنِ ٱلۡمُلۡكُ ٱلۡيَوۡمَۖ لِلَّهِ ٱلۡوَٰحِدِ ٱلۡقَهَّارِ"
    },
    {
      "id": "q-40:16-publishedUzbekFullParent",
      "text": "Улар зоҳир бўлган кунда Аллоҳга улардан ҳеч нарса яширин қолмас. Бу кун мулк кимники? Ёлғиз Қаҳҳор Аллоҳники?"
    },
    {
      "id": "q-40:16-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-41:15",
      "text": "41:15"
    },
    {
      "id": "q-41:15-arabicPublishedParent",
      "text": "فَأَمَّا عَادٞ فَٱسۡتَكۡبَرُواْ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَقَالُواْ مَنۡ أَشَدُّ مِنَّا قُوَّةًۖ أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ ٱلَّذِي خَلَقَهُمۡ هُوَ أَشَدُّ مِنۡهُمۡ قُوَّةٗۖ وَكَانُواْ بِـَٔايَٰتِنَا يَجۡحَدُونَ"
    },
    {
      "id": "q-41:15-publishedUzbekFullParent",
      "text": "Од (қабиласи) ер юзида ноҳақ катта кетдилар ва: «Биздан ҳам кучлироқ ким бор экан?» - дедилар. Уларни яратган Аллоҳ улардан кўра қудратлироқ эканини билмасмидилар?! Улар Бизнинг оятларимизни инкор қилардилар."
    },
    {
      "id": "q-41:15-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-47:4",
      "text": "47:4"
    },
    {
      "id": "q-47:4-arabicPublishedParent",
      "text": "فَإِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُواْ فَضَرۡبَ ٱلرِّقَابِ حَتَّىٰٓ إِذَآ أَثۡخَنتُمُوهُمۡ فَشُدُّواْ ٱلۡوَثَاقَ فَإِمَّا مَنَّۢا بَعۡدُ وَإِمَّا فِدَآءً حَتَّىٰ تَضَعَ ٱلۡحَرۡبُ أَوۡزَارَهَاۚ ذَٰلِكَۖ وَلَوۡ يَشَآءُ ٱللَّهُ لَٱنتَصَرَ مِنۡهُمۡ وَلَٰكِن لِّيَبۡلُوَاْ بَعۡضَكُم بِبَعۡضٖۗ وَٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ فَلَن يُضِلَّ أَعۡمَٰلَهُمۡ"
    },
    {
      "id": "q-47:4-publishedUzbekFullParent",
      "text": "Куфр келтирган кимсалар билан тўқнашганингизда бўйинларига урмоқ лозим. Уларни тор-мор қилганингизда эса маҳкам боғланглар. Ундан кейин ё марҳамат кўрсатиш ёки товон олиш (қолур). То уруш ўз юкларини қўйгунича ҳолат шудир. Аллоҳ хоҳлаганида улардан шундоқ ҳам ғолиб бўларди. Лекин айримларингизни айримларингиз билан синаш учун шундай қилди. Аллоҳнинг йўлида ўлдирилганларнинг амалларини ҳеч қачон зое қилмас."
    },
    {
      "id": "q-47:4-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-48:18",
      "text": "48:18"
    },
    {
      "id": "q-48:18-arabicPublishedParent",
      "text": "۞ لَّقَدۡ رَضِيَ ٱللَّهُ عَنِ ٱلۡمُؤۡمِنِينَ إِذۡ يُبَايِعُونَكَ تَحۡتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِي قُلُوبِهِمۡ فَأَنزَلَ ٱلسَّكِينَةَ عَلَيۡهِمۡ وَأَثَٰبَهُمۡ فَتۡحٗا قَرِيبٗا"
    },
    {
      "id": "q-48:18-publishedUzbekFullParent",
      "text": "Дарҳақиқат, Аллоҳ мўминлардан дарахт остида сизга байъат бераётган пайтларида рози бўлди. Уларнинг қалбларида нима борлигини билди. Бас, уларга оромни индирди ва уларни яқин ғалаба билан мукофотлади."
    },
    {
      "id": "q-48:18-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-51:47",
      "text": "51:47"
    },
    {
      "id": "q-51:47-arabicPublishedParent",
      "text": "وَٱلسَّمَآءَ بَنَيۡنَٰهَا بِأَيۡيْدٖ وَإِنَّا لَمُوسِعُونَ"
    },
    {
      "id": "q-51:47-publishedUzbekFullParent",
      "text": "Самони куч-қудрат ила бино қилдик. Дарҳақиқат, Биз уни кенгайтиргувчимиз."
    },
    {
      "id": "q-51:47-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-51:56",
      "text": "51:56"
    },
    {
      "id": "q-51:56-arabicPublishedParent",
      "text": "وَمَا خَلَقۡتُ ٱلۡجِنَّ وَٱلۡإِنسَ إِلَّا لِيَعۡبُدُونِ"
    },
    {
      "id": "q-51:56-publishedUzbekFullParent",
      "text": "Инсу жинни фақат Менга ибодат қилишлари учунгина яратдим."
    },
    {
      "id": "q-51:56-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-62:3",
      "text": "62:3"
    },
    {
      "id": "q-62:3-arabicPublishedParent",
      "text": "وَءَاخَرِينَ مِنۡهُمۡ لَمَّا يَلۡحَقُواْ بِهِمۡۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ"
    },
    {
      "id": "q-62:3-publishedUzbekFullParent",
      "text": "Ҳали уларга етиб келмаган. Улардан бошқаларга ҳам. У Зот Азиз, Ҳакимдир."
    },
    {
      "id": "q-62:3-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-75:20",
      "text": "75:20"
    },
    {
      "id": "q-75:20-arabicPublishedParent",
      "text": "كَلَّا بَلۡ تُحِبُّونَ ٱلۡعَاجِلَةَ"
    },
    {
      "id": "q-75:20-publishedUzbekFullParent",
      "text": "Йўқ! Балки сизлар нақдни яхши кўрасизлар."
    },
    {
      "id": "q-75:20-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-75:21",
      "text": "75:21"
    },
    {
      "id": "q-75:21-arabicPublishedParent",
      "text": "وَتَذَرُونَ ٱلۡأٓخِرَةَ"
    },
    {
      "id": "q-75:21-publishedUzbekFullParent",
      "text": "Охиратни эса тарк этасизлар."
    },
    {
      "id": "q-75:21-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-79:24",
      "text": "79:24"
    },
    {
      "id": "q-79:24-arabicPublishedParent",
      "text": "فَقَالَ أَنَا۠ رَبُّكُمُ ٱلۡأَعۡلَىٰ"
    },
    {
      "id": "q-79:24-publishedUzbekFullParent",
      "text": "«Мен сизларнинг энг олий Парвардигорингиздирман», деди."
    },
    {
      "id": "q-79:24-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-83:35",
      "text": "83:35"
    },
    {
      "id": "q-83:35-arabicPublishedParent",
      "text": "عَلَى ٱلۡأَرَآئِكِ يَنظُرُونَ"
    },
    {
      "id": "q-83:35-publishedUzbekFullParent",
      "text": "Сўриларда қараб (ўтирадилар)."
    },
    {
      "id": "q-83:35-completeFootnotes",
      "text": ""
    },
    {
      "id": "q-ref-100:6",
      "text": "100:6"
    },
    {
      "id": "q-100:6-arabicPublishedParent",
      "text": "إِنَّ ٱلۡإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٞ"
    },
    {
      "id": "q-100:6-publishedUzbekFullParent",
      "text": "Албатта, инсон ўз Парвардигорига ношукрдир."
    },
    {
      "id": "q-100:6-completeFootnotes",
      "text": ""
    },
    {
