      "text": "﴿他没有生产，也没有被生产；﴾",
      "sentences": [
        {
          "id": "p10.s01",
          "text": "﴿他没有生产，也没有被生产；﴾",
          "segments": [
            {
              "type": "commentary",
              "text": "﴿"
            },
            {
              "type": "quran_excerpt",
              "id": "Q:94",
